// tests/unit/payments-netopia-notice.test.ts
// N4 (spec 2026-10-05 §2.4.6, §2.7.2, §2.7.3 step 1, §2.20.2 "the verifier"): verifying NETOPIA's message, the
// trusted-key list, the quarantine test, the tolerant parse and the answers. Every key here is generated by the test
// (spec §2.2 rule 2). The signing helper below is written from the JWT rules directly, never from the package, so it
// can catch the verifier's mistakes; the certificate is built by hand in DER for the same reason.
import {
  createHash, createHmac, createPublicKey, generateKeyPairSync, randomBytes, sign, type KeyObject
} from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { inspect } from "node:util";
import { describe, expect, it } from "vitest";
import { TypedDomainError } from "@debateai/kernel";
import {
  loadTrustedKeys, netopiaNoticeAnswer, parseNetopiaNotice, publishedIpnKeyFingerprint, quarantinable,
  verifyNetopiaNotice, type NoticeRejectionReason, type NoticeTrust
} from "@debateai/payments-netopia";

/** Made-up POS signatures in NETOPIA's shape, built from pieces (the leak scanner reads long key-like strings). */
const POS = ["AB12", "CD34", "EF56", "GH78", "IJ90"].join("-");
const OTHER_POS = ["ZZ12", "CD34", "EF56", "GH78", "IJ90"].join("-");
const NOW = new Date("2026-10-06T10:00:00.000Z");
const CHARGE_ID = "0123456789abcdef0123456789abcdef";
const TOOL_ORDER_ID = `t-${"0123456789abcdef"}${"0123456789abcd"}`;
const TOKEN = ["made-up", "card-token", "for-the-notice-test"].join("-");

type Pair = Readonly<{ privateKey: KeyObject; publicPem: string }>;
function rsaPair(bits = 2048): Pair {
  const { privateKey, publicKey } = generateKeyPairSync("rsa", { modulusLength: bits });
  return { privateKey, publicPem: publicKey.export({ type: "spki", format: "pem" }).toString() };
}
const MAIN = rsaPair();
const SECOND = rsaPair();
const STRANGER = rsaPair();
const SHORT = rsaPair(1024);

const spkiSha256 = (publicPem: string): string =>
  createHash("sha256").update(createPublicKey(publicPem).export({ type: "spki", format: "der" })).digest("hex");
const trustOf = (...pems: string[]): NoticeTrust => ({ posSignature: POS, keys: loadTrustedKeys(pems.join("\n")) });
const TRUST = trustOf(MAIN.publicPem);

const b64url = (value: Buffer | string): string => Buffer.from(value).toString("base64url");

type SignOptions = Readonly<{
  key?: KeyObject; alg?: string; typ?: string | null; iss?: unknown; aud?: unknown; sub?: unknown; iat?: unknown;
  extra?: Readonly<Record<string, unknown>>; hmacSecret?: string;
}>;
/** A Verification-token for `rawBody`, signed the way NETOPIA's SDKs sign (RS512, aud as an array). */
function signedHeader(rawBody: Buffer, options: SignOptions = {}): string {
  const alg = options.alg ?? "RS512";
  const jose: Record<string, unknown> = { alg };
  if (options.typ !== null) jose.typ = options.typ ?? "JWT";
  const claims: Record<string, unknown> = {
    iss: "iss" in options ? options.iss : "NETOPIA Payments",
    aud: "aud" in options ? options.aud : [POS],
    sub: "sub" in options ? options.sub : createHash("sha512").update(rawBody).digest("base64"),
    iat: "iat" in options ? options.iat : 1_759_744_800,
    ...options.extra
  };
  const input = `${b64url(JSON.stringify(jose))}.${b64url(JSON.stringify(claims))}`;
  const key = options.key ?? MAIN.privateKey;
  const signature = alg === "none" ? Buffer.alloc(0)
    : alg === "HS512" ? createHmac("sha512", options.hmacSecret ?? "").update(input).digest()
      : alg === "RS256" ? sign("sha256", Buffer.from(input), key)
        : sign("sha512", Buffer.from(input), key);
  return `${input}.${b64url(signature)}`;
}

function noticeBody(payment: Readonly<Record<string, unknown>> = {}, orderId: string = CHARGE_ID): Buffer {
  return Buffer.from(JSON.stringify({
    payment: {
      method: "card", ntpID: "1234567", status: 3, amount: 24.2, currency: "USD", code: "00", message: "Approved",
      binding: { token: TOKEN, expireMonth: 11, expireYear: 2030 },
      instrument: { panMasked: "9****5098", issuer: "Test Bank", country: 642 },
      data: { ISSUER_COUNTRY: "642" }, operationDate: "2026-10-06T09:58:00Z",
      ...payment
    },
    order: { orderID: orderId, data: {} }
  }), "utf8");
}

const rejection = (reason: NoticeRejectionReason) => ({ ok: false, reason });

// A minimal self-signed X.509 v1 certificate, DER-encoded by hand (node:crypto cannot make one).
function der(tag: number, content: Buffer): Buffer {
  const length = content.byteLength;
  const head = length < 0x80 ? Buffer.from([length])
    : length < 0x100 ? Buffer.from([0x81, length])
      : Buffer.from([0x82, length >> 8, length & 0xff]);
  return Buffer.concat([Buffer.from([tag]), head, content]);
}
const sequence = (...parts: Buffer[]): Buffer => der(0x30, Buffer.concat(parts));
const SHA256_WITH_RSA = sequence(Buffer.from("06092a864886f70d01010b", "hex"), Buffer.from("0500", "hex"));
function selfSignedCertificatePem(pair: Pair): string {
  const name = sequence(der(0x31, sequence(Buffer.from("0603550403", "hex"), der(0x0c, Buffer.from("NETOPIA test", "utf8")))));
  const validity = sequence(der(0x17, Buffer.from("260101000000Z", "ascii")), der(0x17, Buffer.from("360101000000Z", "ascii")));
  const spki = createPublicKey(pair.publicPem).export({ type: "spki", format: "der" });
  const tbs = sequence(der(0x02, Buffer.from([0x01])), SHA256_WITH_RSA, name, validity, name, spki);
  const signature = sign("sha256", tbs, pair.privateKey);
  const certificate = sequence(tbs, SHA256_WITH_RSA, der(0x03, Buffer.concat([Buffer.from([0x00]), signature])));
  const lines = certificate.toString("base64").match(/.{1,64}/gu) ?? [];
  return `-----BEGIN CERTIFICATE-----\n${lines.join("\n")}\n-----END CERTIFICATE-----\n`;
}

/** The refusal code of a key list, after checking that the error says nothing about the keys. */
function refusalOf(pem: string): string {
  try {
    loadTrustedKeys(pem);
  } catch (error) {
    expect(error).toBeInstanceOf(TypedDomainError);
    expect((error as Error).message).toBe("the trusted NETOPIA key list is invalid");
    return (error as TypedDomainError).code;
  }
  throw new Error("loadTrustedKeys accepted the list");
}

describe("N4 — verifyNetopiaNotice (spec §2.4.6)", () => {
  it("accepts a genuine message and names the key that verified it", () => {
    const body = noticeBody();
    expect(verifyNetopiaNotice(body, signedHeader(body), TRUST))
      .toEqual({ ok: true, keyFingerprint: spkiSha256(MAIN.publicPem), jwtIat: "1759744800" });
  });

  it("refuses a message signed by a key we do not trust, and says nothing but the reason", () => {
    const body = noticeBody();
    const result = verifyNetopiaNotice(body, signedHeader(body, { key: STRANGER.privateKey }), TRUST);
    expect(result).toEqual(rejection("NOTICE_SIGNATURE_INVALID"));
    expect(Object.keys(result).sort()).toEqual(["ok", "reason"]);
  });

  it("tries every trusted key and records which one verified", () => {
    const body = noticeBody();
    const result = verifyNetopiaNotice(body, signedHeader(body, { key: SECOND.privateKey }), trustOf(MAIN.publicPem, SECOND.publicPem));
    expect(result).toEqual({ ok: true, keyFingerprint: spkiSha256(SECOND.publicPem), jwtIat: "1759744800" });
  });

  it.each([
    ["none", {}],
    ["HS512", { hmacSecret: MAIN.publicPem }],
    ["RS256", {}],
    ["PS512", {}],
    ["rs512", {}]
  ] as const)("refuses alg %s before any key is used", (alg, extra) => {
    const body = noticeBody();
    expect(verifyNetopiaNotice(body, signedHeader(body, { alg, ...extra }), TRUST)).toEqual(rejection("NOTICE_ALG_REFUSED"));
  });

  it("accepts a header without typ and refuses one whose typ is not JWT", () => {
    const body = noticeBody();
    expect(verifyNetopiaNotice(body, signedHeader(body, { typ: null }), TRUST).ok).toBe(true);
    expect(verifyNetopiaNotice(body, signedHeader(body, { typ: "JWS" }), TRUST)).toEqual(rejection("NOTICE_ALG_REFUSED"));
  });

  it("refuses a missing or malformed header", () => {
    const body = noticeBody();
    const [head, claims, signature] = signedHeader(body).split(".") as [string, string, string];
    for (const header of [
      undefined, "", "   ", `${head}.${claims}`, `${head}.${claims}.${signature}.${signature}`,
      `${head}=.${claims}.${signature}`, `${b64url("not json")}.${claims}.${signature}`, `.${claims}.${signature}`,
      `${head}.${claims}.${signature}*`
    ]) {
      expect(verifyNetopiaNotice(body, header, TRUST), String(header)).toEqual(rejection("NOTICE_HEADER_MISSING"));
    }
  });

  it("refuses a signature that does not cover this header and payload", () => {
    const body = noticeBody();
    const [head, claims] = signedHeader(body).split(".") as [string, string, string];
    expect(verifyNetopiaNotice(body, `${head}.${claims}.${b64url(Buffer.alloc(256, 1))}`, TRUST))
      .toEqual(rejection("NOTICE_SIGNATURE_INVALID"));
    expect(verifyNetopiaNotice(body, `${head}.${claims}.`, TRUST)).toEqual(rejection("NOTICE_SIGNATURE_INVALID"));
    const forged = b64url(JSON.stringify({ iss: "NETOPIA Payments", aud: [POS], sub: "x" }));
    const genuine = signedHeader(body).split(".")[2]!;
    expect(verifyNetopiaNotice(body, `${head}.${forged}.${genuine}`, TRUST)).toEqual(rejection("NOTICE_SIGNATURE_INVALID"));
  });

  it("ignores a hand-built trust entry whose key is shorter than 2,048 bits", () => {
    const body = noticeBody();
    const shortTrust: NoticeTrust = { posSignature: POS, keys: [{ key: createPublicKey(SHORT.publicPem), fingerprint: "short" }] };
    expect(verifyNetopiaNotice(body, signedHeader(body, { key: SHORT.privateKey }), shortTrust))
      .toEqual(rejection("NOTICE_SIGNATURE_INVALID"));
  });

  it("requires iss to be exactly NETOPIA Payments", () => {
    const body = noticeBody();
    for (const iss of ["NETOPIA", "netopia payments", "NETOPIA Payments ", undefined, 1]) {
      expect(verifyNetopiaNotice(body, signedHeader(body, { iss }), TRUST), String(iss)).toEqual(rejection("NOTICE_ISSUER_INVALID"));
    }
  });

  it("requires aud, as a string or an array, to name our POS signature", () => {
    const body = noticeBody();
    expect(verifyNetopiaNotice(body, signedHeader(body, { aud: POS }), TRUST).ok).toBe(true);
    expect(verifyNetopiaNotice(body, signedHeader(body, { aud: [OTHER_POS, POS] }), TRUST).ok).toBe(true);
    for (const aud of [OTHER_POS, [OTHER_POS], [], undefined, "", POS.toLowerCase()]) {
      expect(verifyNetopiaNotice(body, signedHeader(body, { aud }), TRUST), String(aud)).toEqual(rejection("NOTICE_AUDIENCE_INVALID"));
    }
    const blankTrust: NoticeTrust = { posSignature: "", keys: TRUST.keys };
    expect(verifyNetopiaNotice(body, signedHeader(body, { aud: "" }), blankTrust)).toEqual(rejection("NOTICE_AUDIENCE_INVALID"));
  });

  it("binds the message to the exact bytes received, non-ASCII and non-UTF-8 bytes included", () => {
    const spaced = Buffer.from(`{ "payment": { "status": 3, "message": "Plată aprobată" }, "order": { "orderID": "${CHARGE_ID}" } }`, "utf8");
    const raw = Buffer.concat([spaced, Buffer.from([0xff, 0x0a])]);
    expect(verifyNetopiaNotice(raw, signedHeader(raw), TRUST).ok).toBe(true);
    // A body re-encoded on the way (parsed and serialised again) no longer matches.
    const reencoded = Buffer.from(JSON.stringify(JSON.parse(spaced.toString("utf8"))), "utf8");
    expect(verifyNetopiaNotice(reencoded, signedHeader(spaced), TRUST)).toEqual(rejection("NOTICE_BODY_HASH_INVALID"));
    const digest = createHash("sha512").update(raw);
    for (const sub of [
      createHash("sha512").update(raw).digest("hex"), digest.copy().digest("base64url"), "short", 7, undefined,
      createHash("sha256").update(raw).digest("base64")
    ]) {
      expect(verifyNetopiaNotice(raw, signedHeader(raw, { sub }), TRUST), String(sub)).toEqual(rejection("NOTICE_BODY_HASH_INVALID"));
    }
  });

  it("checks no time claim, and records iat as received", () => {
    const body = noticeBody();
    const expired = signedHeader(body, { iat: 1_759_744_800_000, extra: { exp: 1, nbf: 9_999_999_999_999 } });
    expect(verifyNetopiaNotice(body, expired, TRUST)).toEqual({
      ok: true, keyFingerprint: spkiSha256(MAIN.publicPem), jwtIat: "1759744800000"
    });
    expect(verifyNetopiaNotice(body, signedHeader(body, { iat: undefined }), TRUST)).toMatchObject({ ok: true, jwtIat: null });
    expect(verifyNetopiaNotice(body, signedHeader(body, { iat: { at: 1 } }), TRUST)).toMatchObject({ ok: true, jwtIat: null });
  });
});

describe("N4 — loadTrustedKeys", () => {
  it("reads PUBLIC KEY blocks between comments and fingerprints each key", () => {
    const keys = loadTrustedKeys(`# NETOPIA's key\n${MAIN.publicPem}\n# a second one\n${SECOND.publicPem}`);
    expect(keys.map((trusted) => trusted.fingerprint)).toEqual([spkiSha256(MAIN.publicPem), spkiSha256(SECOND.publicPem)]);
    expect(keys.every((trusted) => /^[0-9a-f]{64}$/u.test(trusted.fingerprint))).toBe(true);
  });

  it("reads a CERTIFICATE block as its public key, which then verifies messages", () => {
    const pair = rsaPair();
    const keys = loadTrustedKeys(selfSignedCertificatePem(pair));
    expect(keys.map((trusted) => trusted.fingerprint)).toEqual([spkiSha256(pair.publicPem)]);
    const body = noticeBody();
    expect(verifyNetopiaNotice(body, signedHeader(body, { key: pair.privateKey }), { posSignature: POS, keys }).ok).toBe(true);
  });

  it("keeps a key listed twice once", () => {
    expect(loadTrustedKeys([MAIN.publicPem, SECOND.publicPem, MAIN.publicPem].join("\n"))).toHaveLength(2);
  });

  it("refuses a list it cannot trust, naming why and never the keys", () => {
    const ec = generateKeyPairSync("ec", { namedCurve: "P-256" }).publicKey.export({ type: "spki", format: "pem" }).toString();
    const pkcs1 = createPublicKey(MAIN.publicPem).export({ type: "pkcs1", format: "pem" }).toString();
    const privatePem = MAIN.privateKey.export({ type: "pkcs8", format: "pem" }).toString();
    const unterminated = MAIN.publicPem.replace("-----END PUBLIC KEY-----", "");
    const cases: ReadonlyArray<readonly [string, string]> = [
      ["", "NO_KEY"],
      ["# only a comment\n", "NO_KEY"],
      [privatePem, "BLOCK_TYPE"],
      [pkcs1, "BLOCK_TYPE"],
      [ec, "NOT_RSA"],
      [SHORT.publicPem, "TOO_SHORT"],
      [unterminated, "BLOCK_UNTERMINATED"],
      [`${MAIN.publicPem}\n-----END PUBLIC KEY-----\n`, "BLOCK_UNTERMINATED"],
      ["-----BEGIN PUBLIC KEY-----\nnot base64!\n-----END PUBLIC KEY-----\n", "UNREADABLE"],
      ["-----BEGIN PUBLIC KEY-----\nAAAA\n-----END PUBLIC KEY-----\n", "UNREADABLE"],
      [`${MAIN.publicPem}\n${SHORT.publicPem}`, "TOO_SHORT"]
    ];
    for (const [pem, why] of cases) expect(refusalOf(pem), why).toBe(`NETOPIA_IPN_KEYS_INVALID:${why}`);
  });

  it("ships NETOPIA's published plugin key, with where it was read and its fingerprint", () => {
    const expected = ["eeba3b065067fb01", "c2389850c7a88845", "6dfd31332d67ed9b", "630dae24753478d7"].join("");
    const published = readFileSync(resolve(import.meta.dirname, "../../deploy/vps/netopia/published-ipn-key.pem"), "utf8");
    expect(publishedIpnKeyFingerprint()).toBe(expected);
    const keys = loadTrustedKeys(published);
    expect(keys.map((trusted) => trusted.fingerprint)).toEqual([expected]);
    expect(keys[0]!.key.asymmetricKeyDetails?.modulusLength).toBe(2048);
    expect(published).toContain(`# SPKI SHA-256: ${expected}`);
    expect(published).toContain("https://github.com/netopiapayments/WooCommerce/blob/2b80c8d3fbea9360f063b4fe3684401c562b3587/"
      + "netopia-payments-payment-gateway/v2/wc-netopiapayments-gateway.php");
    expect(published.match(/-----BEGIN /gu)).toHaveLength(1);
    expect(published).not.toMatch(/PRIVATE/u);
  });
});

describe("N4 — quarantinable (spec §2.4.6, §2.7.4)", () => {
  const strangerHeader = (body: Buffer, aud: unknown = [POS]) => signedHeader(body, { key: STRANGER.privateKey, aud });

  it("keeps a rejected message that names our POS and one of our order forms", () => {
    for (const orderId of [CHARGE_ID, TOOL_ORDER_ID]) {
      const body = noticeBody({}, orderId);
      expect(quarantinable(body, strangerHeader(body), POS), orderId).toBe(true);
    }
    const body = noticeBody();
    expect(quarantinable(body, strangerHeader(body, POS), POS)).toBe(true);
  });

  it("drops anything else", () => {
    const ours = noticeBody();
    expect(quarantinable(ours, strangerHeader(ours, [OTHER_POS]), POS)).toBe(false);
    expect(quarantinable(ours, undefined, POS)).toBe(false);
    expect(quarantinable(ours, strangerHeader(ours).split(".").slice(0, 2).join("."), POS)).toBe(false);
    for (const orderId of ["12345", CHARGE_ID.toUpperCase(), `t-${"0".repeat(29)}`, `${CHARGE_ID}0`]) {
      const body = noticeBody({}, orderId);
      expect(quarantinable(body, strangerHeader(body), POS), orderId).toBe(false);
    }
    const garbage = Buffer.from("not json", "utf8");
    expect(quarantinable(garbage, strangerHeader(garbage), POS)).toBe(false);
  });
});

describe("N4 — parseNetopiaNotice (spec §2.7.3 step 1, §2.4.3, §2.5.2)", () => {
  it("reads every allow-listed field and the saved card", () => {
    const parsed = parseNetopiaNotice(noticeBody(), NOW);
    expect(parsed).toMatchObject({
      readable: true, orderId: CHARGE_ID, providerPaymentId: "1234567", providerStatus: 3, amountText: "24.2",
      currency: "USD", cardCountry: "RO", code: "00", message: "Approved",
      occurredAt: new Date("2026-10-06T09:58:00.000Z")
    });
    expect(parsed.savedCard).toMatchObject({ expMonth: 11, expYear: 2030, last4: "5098" });
    expect(parsed.savedCard?.token.reveal()).toBe(TOKEN);
    expect(parsed.allowed).toEqual({
      orderID: CHARGE_ID, ntpID: "1234567", status: 3, amount: "24.2", currency: "USD", code: "00", message: "Approved",
      cardCountry: "RO", last4: "5098", expireMonth: 11, expireYear: 2030
    });
  });

  it("never lets the token out in print", () => {
    const parsed = parseNetopiaNotice(noticeBody(), NOW);
    expect(JSON.stringify(parsed)).not.toContain(TOKEN);
    expect(JSON.stringify(parsed.allowed)).not.toContain(TOKEN);
    expect(inspect(parsed, { depth: 10 })).not.toContain(TOKEN);
    expect(String(parsed.savedCard?.token)).toBe("[token]");
  });

  it("keeps the amount as NETOPIA wrote it", () => {
    const raw = Buffer.from(`{"payment":{"ntpID":"9","status":5,"amount":1.00,"currency":"USD"},"order":{"orderID":"${CHARGE_ID}"}}`, "utf8");
    expect(parseNetopiaNotice(raw, NOW)).toMatchObject({ readable: true, amountText: "1.00", providerStatus: 5, savedCard: null });
  });

  it("takes the token from the first path that holds one, and treats 0 as an unknown expiry", () => {
    const atInstrument = parseNetopiaNotice(noticeBody({
      binding: { expireMonth: 0, expireYear: 0 }, instrument: { panMasked: "4111********1111", token: TOKEN, country: 642 }
    }), NOW);
    expect(atInstrument.savedCard?.token.reveal()).toBe(TOKEN);
    expect(atInstrument.savedCard).toMatchObject({ expMonth: null, expYear: null, last4: "1111" });
    const atPayment = parseNetopiaNotice(noticeBody({ binding: { token: "", expireMonth: 3, expireYear: 2031 }, token: TOKEN }), NOW);
    expect(atPayment.savedCard?.token.reveal()).toBe(TOKEN);
    expect(atPayment.savedCard).toMatchObject({ expMonth: 3, expYear: 2031 });
    const tooShort = parseNetopiaNotice(noticeBody({ binding: { token: "abc" }, token: TOKEN }), NOW);
    expect(tooShort.savedCard?.token.reveal()).toBe(TOKEN);
    const none = parseNetopiaNotice(noticeBody({ binding: { expireMonth: 11, expireYear: 2030 } }), NOW);
    expect(none.savedCard).toBeNull();
    expect(none.allowed).toMatchObject({ last4: "5098", expireMonth: null, expireYear: null });
  });

  it("reads the card's country from the instrument, else from ISSUER_COUNTRY", () => {
    expect(parseNetopiaNotice(noticeBody({ instrument: { country: 0 }, data: { ISSUER_COUNTRY: "642" } }), NOW).cardCountry).toBe("RO");
    expect(parseNetopiaNotice(noticeBody({ instrument: {}, data: { ISSUER_COUNTRY: "RO" } }), NOW).cardCountry).toBe("RO");
    expect(parseNetopiaNotice(noticeBody({ instrument: {}, data: {} }), NOW).cardCountry).toBeNull();
  });

  it("dates the payment only from a zoned, plausible time", () => {
    for (const operationDate of ["0001-01-01T00:00:00", "2026-10-06T09:58:00", "2026-10-06T10:30:00Z", 1_759_744_800, null]) {
      expect(parseNetopiaNotice(noticeBody({ operationDate }), NOW).occurredAt, String(operationDate)).toBeNull();
    }
  });

  it("stores a field it cannot read as null and keeps the rest", () => {
    const parsed = parseNetopiaNotice(Buffer.from(JSON.stringify({
      payment: {
        ntpID: "has space", status: "three", amount: "abc", currency: "usd", code: "0 0", message: "line\nbreak",
        instrument: { panMasked: 5098 }
      },
      order: { orderID: { nested: true } }
    }), "utf8"), NOW);
    expect(parsed).toMatchObject({
      readable: true, orderId: null, providerPaymentId: null, providerStatus: null, amountText: null, currency: null,
      code: null, message: null, cardCountry: null, savedCard: null, occurredAt: null
    });
    const noOrder = parseNetopiaNotice(Buffer.from(JSON.stringify({ payment: { status: 3, ntpID: "77" } }), "utf8"), NOW);
    expect(noOrder).toMatchObject({ readable: true, orderId: null, providerStatus: 3, providerPaymentId: "77" });
  });

  it("marks bytes that are not a JSON object as unreadable, and never throws", () => {
    for (const raw of [Buffer.from([0xff, 0xfe, 0x7b]), Buffer.from("[1,2]"), Buffer.from("null"), Buffer.alloc(0), Buffer.from("{")]) {
      expect(parseNetopiaNotice(raw, NOW)).toEqual({
        readable: false, orderId: null, providerPaymentId: null, providerStatus: null, amountText: null, currency: null,
        cardCountry: null, code: null, message: null, savedCard: null, occurredAt: null, allowed: {}
      });
    }
    for (let round = 0; round < 50; round += 1) {
      expect(() => parseNetopiaNotice(randomBytes(64), NOW)).not.toThrow();
    }
  });
});

describe("N4 — netopiaNoticeAnswer (spec §2.7.2)", () => {
  it("answers a stored message with NETOPIA's success body", () => {
    expect(netopiaNoticeAnswer("OK")).toEqual({ status: 200, body: "{\"errorType\":0,\"errorCode\":0,\"errorMessage\":\"OK\"}" });
  });

  it("asks NETOPIA to try again when the store failed", () => {
    expect(netopiaNoticeAnswer("STORE_FAILED")).toEqual({ status: 503, body: "{\"errorType\":1,\"errorCode\":1,\"errorMessage\":\"retry\"}" });
  });

  it.each([
    ["NOTICE_HEADER_MISSING", 268435713], ["NOTICE_ALG_REFUSED", 268435713], ["NOTICE_ISSUER_INVALID", 268435713],
    ["NOTICE_SIGNATURE_INVALID", 268435714], ["NOTICE_AUDIENCE_INVALID", 268435717], ["NOTICE_BODY_HASH_INVALID", 268435718]
  ] as const)("asks NETOPIA to try again for %s, with its SDK's code", (reason, code) => {
    const answer = netopiaNoticeAnswer(reason);
    expect(answer).toEqual({ status: 503, body: `{"errorType":1,"errorCode":${code},"errorMessage":"retry"}` });
    expect(JSON.parse(answer.body)).toEqual({ errorType: 1, errorCode: code, errorMessage: "retry" });
  });
});
